impl Carrying {
    /// Measures this variant's wire encoding.
    #[must_use]
    pub fn measure(&self) -> u32 {
        match self {
            Self::Key(record) => 1_u32.checked_add(CarriedKey::measure(record)).expect("schema ceilings fit u32"),
            Self::Value(record) => 1_u32.checked_add(CarriedValue::measure(record)).expect("schema ceilings fit u32"),
            Self::Moved(record) => 1_u32.checked_add(CarriedMoved::measure(record)).expect("schema ceilings fit u32"),
        }
    }

    /// Writes this variant's tag and payload.
    pub fn encode(&self, writer: &mut skein_lib::Writer) -> Result<(), skein_lib::Overflow> {
        match self {
            Self::Key(record) => { writer.put(&[0_u8])?; record.encode(writer)?; }
            Self::Value(record) => { writer.put(&[1_u8])?; record.encode(writer)?; }
            Self::Moved(record) => { writer.put(&[2_u8])?; record.encode(writer)?; }
        }
        Ok(())
    }

    /// Reads a whole variant and refuses trailing bytes.
    pub fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::decode_from(limits, reader)?;
        if !reader.is_empty() { return Err(Problem { path: Path::CarryingTag, reason: skein_codec::Reason::Trailing }); }
        Ok(value)
    }

    fn decode_from(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: Path::CarryingTag, reason: skein_codec::Reason::Short })?;
        let value = match tag {
            0 => Self::Key(CarriedKey::decode_from(limits, reader)?),
            1 => Self::Value(CarriedValue::decode_from(limits, reader)?),
            2 => Self::Moved(CarriedMoved::decode_from(limits, reader)?),
            _ => return Err(Problem { path: Path::CarryingTag, reason: skein_codec::Reason::Tag }),
        };
        Ok(value)
    }
}

impl Carried {
    /// Measures this record's wire encoding.
    #[must_use]
    pub fn measure(&self) -> u32 {
        let mut size = 0_u32;
        size = size.checked_add(2).expect("schema ceilings fit u32");
        let field_value = &self.value;
        size = size.checked_add(field_value.measure()).expect("schema ceilings fit u32");
        size
    }

    /// Writes into a writer with room for the measured bytes.
    pub fn encode(&self, writer: &mut skein_lib::Writer) -> Result<(), skein_lib::Overflow> {
        writer.put(&1_u16.to_be_bytes())?;
        let field_value = &self.value;
        field_value.encode(writer)?;
        Ok(())
    }

    /// Reads a whole record and refuses trailing bytes.
    pub fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::decode_from(limits, reader)?;
        if !reader.is_empty() { return Err(Problem { path: Path::CarriedTail, reason: skein_codec::Reason::Trailing }); }
        Ok(value)
    }

    fn decode_from(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let version = reader.u16().ok_or(Problem { path: Path::CarriedVersion, reason: skein_codec::Reason::Short })?;
        if version != 1 { return Err(Problem { path: Path::CarriedVersion, reason: skein_codec::Reason::Version }); }
        let decoded_value = Carrying::decode_from(limits, reader)?;
        Ok(Self { value: decoded_value })
    }
}

